SELECT *
FROM t_smart_job_log


        AND ( job_name ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR param ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR execute_result ILIKE CONCAT('%', #{query.searchWord}, '%')
        OR create_name ILIKE CONCAT('%', #{query.searchWord}, '%')
        )


        AND job_id = #{query.jobId}


        AND success = #{query.successFlag}


        AND TO_CHAR(execute_start_time, 'YYYY-MM-DD') >= #{query.startTime}


        AND TO_CHAR(execute_start_time, 'YYYY-MM-DD') <= #{query.endTime}



    ORDER BY log_id DESC
